package com.nextrade.engine.risk; import java.util.*; public final class RiskEngine {private final List<RiskRule> rules;public RiskEngine(List<RiskRule> rules){this.rules=List.copyOf(rules);}public RiskDecision evaluate(RiskContext ctx){for(RiskRule r:rules){RiskDecision d=r.evaluate(ctx);if(!d.allowed())return d;}return RiskDecision.allow();}public List<RiskDecision> evaluateAll(RiskContext c){return rules.stream().map(r->r.evaluate(c)).toList();}}
